#!/usr/bin/env node
// Generates the Android theme (AcerolaColors.kt and Shape.kt) from the acerola-brand tokens.json, as the
// acerola-design skill asks (section 11): same role names on every platform.
//
//   node scripts/design/android-theme.mjs                  → reads https://cdn.acerola.app/brand/tokens.json
//   node scripts/design/android-theme.mjs <tokens.json>    → reads a local file (e.g. ../acerola-brand/…)
//
// Never edit the generated files by hand: change the brand and run this again.
// Messages printed to the terminal stay in Portuguese: people read them.

import { readFile, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = join(ROOT, 'acerola/android/ui/src/main/java/br/acerola/comic/common/ux/theme');
const SOURCE = process.argv[2] ?? 'https://cdn.acerola.app/brand/tokens.json';
const PACKAGE = 'br.acerola.comic.common.ux.theme';

const HEADER = `// Generated by scripts/design/android-theme.mjs from the acerola-brand tokens.json. Do not
// edit: change the brand and run \`node scripts/design/android-theme.mjs\` again.`;

const pascal = (name) => name.replace(/(^|-)(\w)/g, (_, __, c) => c.toUpperCase());

async function load() {
	if (/^https?:/.test(SOURCE)) {
		const response = await fetch(SOURCE);
		if (!response.ok) throw new Error(`não deu para baixar ${SOURCE}: ${response.status}`);
		return response.json();
	}
	return JSON.parse(await readFile(SOURCE, 'utf8'));
}

/** `#rrggbb` → `Color(0xFFRRGGBB)`; `var(--x)` resolves inside the same mode. */
function color(value, block, name) {
	const ref = /^var\(--([\w-]+)\)$/.exec(value);
	if (ref) return color(block[ref[1]], block, ref[1]);
	const hex = /^#([0-9a-f]{6})$/i.exec(value);
	if (!hex) throw new Error(`cor inválida em ${name}: ${value}`);
	return `Color(0xFF${hex[1].toUpperCase()})`;
}

function colorObject(name, block) {
	const lines = Object.entries(block)
		.filter(([key]) => key !== 'color-scheme')
		.map(([key, value]) => `        val ${pascal(key)} = ${color(value, block, key)}`);
	return `    object ${name} {\n${lines.join('\n')}\n    }`;
}

/** `32px` → `32.dp`, `2.5rem` → `40.dp` (16px base). */
function dp(value) {
	const px = /^([\d.]+)px$/.exec(value);
	if (px) return `${Number(px[1])}.dp`;
	const rem = /^([\d.]+)rem$/.exec(value);
	if (rem) return `${Number(rem[1]) * 16}.dp`;
	throw new Error(`medida inválida: ${value}`);
}

const tokens = await load();
const shared = tokens.shared;

const colorKt = `${HEADER}
package ${PACKAGE}

import androidx.compose.ui.graphics.Color

// One palette, only the mode changes: Dark is the default, Light follows the system.
// \`*Soft\` is a background and the plain tone is the text on it; never a colored border.
object AcerolaColors {
${colorObject('Dark', tokens.dark)}

${colorObject('Light', tokens.light)}

    // Over a cover or art, the same in both modes on purpose.
    val Scrim = ${color(shared.scrim, shared, 'scrim')}
    val OnScrim = ${color(shared['on-scrim'], shared, 'on-scrim')}
}
`;

const radii = Object.entries(shared)
	.filter(([key]) => key.startsWith('radius-') && key !== 'radius-full')
	.map(([key, value]) => `    val ${pascal(key.slice('radius-'.length))} = RoundedCornerShape(${dp(value)})`);

const shapeKt = `${HEADER}
package ${PACKAGE}

import androidx.compose.foundation.shape.CircleShape
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.ui.unit.dp

// Only these radii: Sheet (whole panel), Card (large card, toast, notice), Tile (number block,
// list row, cover), Inner (inside a card: field, small cover, icon) and Full (pill, chip, button).
object AcerolaShapes {
${radii.join('\n')}
    val Full = CircleShape
}

object AcerolaDimens {
    // Minimum touch target.
    val ControlHeight = ${dp(shared['control-height'])}
}
`;

await writeFile(join(OUT, 'AcerolaColors.kt'), colorKt);
await writeFile(join(OUT, 'Shape.kt'), shapeKt);
console.log(`tema Android gerado de ${SOURCE}: AcerolaColors.kt e Shape.kt`);
